// err is ErrBadResolverState.
func (ccr *ccResolverWrapper) poll(err error) {
	ccr.mu.Lock()
	defer ccr.mu.Unlock()
	if err != balancer.ErrBadResolverState {
		// stop polling
		if ccr.polling != nil {
			close(ccr.polling)
			ccr.polling = nil
		}
		return
	}
	if ccr.polling != nil {
		// already polling
		return
	}
	p := make(chan struct{})
	ccr.polling = p
	go func() {
		for i := 0; ; i++ {
			ccr.resolveNow(resolver.ResolveNowOption{})
			t := time.NewTimer(resolverBackoff(i))
