type State struct {
	Addresses []Address
	// ServiceConfig is the parsed service config result. It may contain either
	// a Config or an Err.
	ServiceConfig *serviceconfig.ParseResult
}

type ClientConn interface {
	// UpdateState updates the state of the ClientConn appropriately.
	UpdateState(State)
	// ReportError notifies gRPC that the resolver encountered an error. The ClientConn will pass this error to the balancer.
	ReportError(error)
	// ParseServiceConfig parses the provided service config and returns an object that contains the parsed config or an error.
	ParseServiceConfig(serviceConfigJSON string) *serviceconfig.ParseResult
	// NewAddress is called by resolver to notify ClientConn a new list
	// of resolved addresses.
	// The address list should be the complete list of resolved addresses.
	//
	// Deprecated: Use UpdateState instead.
	NewAddress(addresses []Address)
	// NewServiceConfig is called by resolver to notify ClientConn a new
	// service config. The service config should be provided as a json string.
	//
	// Deprecated: Use UpdateState instead.
	NewServiceConfig(serviceConfig string)
}

type V2Balancer interface {
	// UpdateClientConnState is called by gRPC when the state of the ClientConn changes.
	// It returns ErrBadResolverState if the resolver state is unusable and should be retried.
	UpdateClientConnState(ClientConnState) error
	// ResolverError is called by gRPC when the name resolver reports an error.
	ResolverError(error)
	// UpdateSubConnState is called by gRPC when the state of a SubConn changes.
	UpdateSubConnState(SubConn, SubConnState)
	// Close closes the balancer.
	Close()
}

func (ccr *ccResolverWrapper) UpdateState(s resolver.State) {
	if ccr.isDone() {
		return
	}
	ccr.cc.blockingpicker.updateConnectionError(nil)
	grpclog.Infof("ccResolverWrapper: sending update to cc: %v", s)
	if channelz.IsOn() {
		ccr.addChannelzTraceEvent(s)
	}
	ccr.cc.updateResolverState(s)
	ccr.curState = s
}

func (cc *ClientConn) updateResolverState(s resolver.State) error {
	cc.mu.Lock()
	defer cc.mu.Unlock()
	if cc.conns == nil {
		return nil
	}

	if cc.dopts.disableServiceConfig || s.ServiceConfig == nil {
		if cc.dopts.defaultServiceConfig != nil && cc.sc == nil {
			cc.applyServiceConfig(cc.dopts.defaultServiceConfig)
		}
	} else if s.ServiceConfig.Err == nil {
		if sc, ok := s.ServiceConfig.Config.(*ServiceConfig); ok {
			cc.applyServiceConfig(sc)
		}
	}

	var balCfg serviceconfig.LoadBalancingConfig
	if cc.dopts.balancerBuilder == nil {
		var newBalancerName string
		if cc.sc != nil && cc.sc.lbConfig != nil {
			newBalancerName = cc.sc.lbConfig.name
			balCfg = cc.sc.lbConfig.cfg
		} else {
			var isGRPCLB bool
			for _, a := range s.Addresses {
				if a.Type == resolver.GRPCLB {
					isGRPCLB = true
					break
				}
			}
			if isGRPCLB {
				newBalancerName = grpclbName
			} else if cc.sc != nil && cc.sc.LB != nil {
				newBalancerName = *cc.sc.LB
			} else {
				newBalancerName = PickFirstBalancerName
			}
		}
		cc.switchBalancer(newBalancerName)
	} else if cc.balancerWrapper == nil {
		cc.curBalancerName = cc.dopts.balancerBuilder.Name()
		cc.balancerWrapper = newCCBalancerWrapper(cc, cc.dopts.balancerBuilder, cc.balancerBuildOpts)
	}

	cc.balancerWrapper.updateClientConnState(&balancer.ClientConnState{ResolverState: s, BalancerConfig: balCfg})
	return nil
}

func (ccr *ccResolverWrapper) ParseServiceConfig(serviceConfigJSON string) *serviceconfig.ParseResult {
	config, err := parseServiceConfig(serviceConfigJSON)
	return &serviceconfig.ParseResult{Config: config, Err: err}
}

func (ccr *ccResolverWrapper) NewServiceConfig(sc string) {
	if ccr.isDone() {
		return
	}
	grpclog.Infof("ccResolverWrapper: got new service config: %v", sc)
	parsed := ccr.ParseServiceConfig(sc)
	if parsed.Err != nil {
		return
	}
	state := resolver.State{Addresses: ccr.curState.Addresses, ServiceConfig: parsed}
	if channelz.IsOn() {
		ccr.addChannelzTraceEvent(state)
	}
	ccr.curState.ServiceConfig = parsed
	ccr.cc.updateResolverState(ccr.curState)
}

func (ccr *ccResolverWrapper) addChannelzTraceEvent(s resolver.State) {
	var updates []string
	var oldSC, newSC *ServiceConfig
	if ccr.curState.ServiceConfig != nil {
		oldSC, _ = ccr.curState.ServiceConfig.Config.(*ServiceConfig)
	}
	if s.ServiceConfig != nil {
		newSC, _ = s.ServiceConfig.Config.(*ServiceConfig)
	}
	if (oldSC == nil) != (newSC == nil) || (oldSC != nil && newSC != nil && oldSC.rawJSONString != newSC.rawJSONString) {
		updates = append(updates, "service config updated")
	}
	if len(ccr.curState.Addresses) > 0 && len(s.Addresses) == 0 {
		updates = append(updates, "resolver returned an empty address list")
	} else if len(ccr.curState.Addresses) == 0 && len(s.Addresses) > 0 {
		updates = append(updates, "resolver returned new addresses")
	}
	channelz.AddTraceEvent(ccr.cc.channelzID, &channelz.TraceEventDesc{
		Desc:     fmt.Sprintf("Resolver state updated: %+v (%v)", s, strings.Join(updates, "; ")),
		Severity: channelz.CtINFO,
	})
}

func (b *baseBalancer) UpdateClientConnState(s balancer.ClientConnState) error {
	if grpclog.V(2) {
		grpclog.Infoln("base.baseBalancer: got new ClientConn state: ", s)
	}
	addrsSet := make(map[resolver.Address]struct{})
	for _, a := range s.ResolverState.Addresses {
		addrsSet[a] = struct{}{}
		if _, ok := b.subConns[a]; !ok {
			sc, err := b.cc.NewSubConn([]resolver.Address{a}, balancer.NewSubConnOptions{HealthCheckEnabled: b.config.HealthCheck})
			if err != nil {
				grpclog.Warningf("base.baseBalancer: failed to create new SubConn: %v", err)
				continue
			}
			b.subConns[a] = sc
			b.scStates[sc] = connectivity.Idle
			sc.Connect()
		}
	}
	for a, sc := range b.subConns {
		if _, ok := addrsSet[a]; !ok {
			b.cc.RemoveSubConn(sc)
			delete(b.subConns, a)
		}
	}
	return nil
}

func (b *baseBalancer) ResolverError(err error) {
	b.picker = NewErrPicker(err)
	b.cc.UpdateBalancerState(connectivity.TransientFailure, b.picker)
}

func (lb *lbBalancer) UpdateClientConnState(ccs balancer.ClientConnState) error {
	if grpclog.V(2) {
		grpclog.Infof("lbBalancer: UpdateClientConnState: %+v", ccs)
	}
	gc, _ := ccs.BalancerConfig.(*grpclbServiceConfig)
	lb.handleServiceConfig(gc)

	addrs := ccs.ResolverState.Addresses
	if len(addrs) <= 0 {
		return nil
	}

	var remoteBalancerAddrs, backendAddrs []resolver.Address
	for _, a := range addrs {
		if a.Type == resolver.GRPCLB {
			a.Type = resolver.Backend
			remoteBalancerAddrs = append(remoteBalancerAddrs, a)
		} else {
			backendAddrs = append(backendAddrs, a)
		}
	}

	if lb.ccRemoteLB == nil {
		if len(remoteBalancerAddrs) <= 0 {
			grpclog.Errorf("grpclb: no remote balancer address is available, should never happen")
			return nil
		}
		lb.dialRemoteLB(remoteBalancerAddrs[0].ServerName)
		go lb.fallbackToBackendsAfter(lb.fallbackTimeout)
	}

	lb.manualResolver.UpdateState(resolver.State{Addresses: remoteBalancerAddrs})

	lb.mu.Lock()
	lb.resolvedBackendAddrs = backendAddrs
	if lb.inFallback {
		lb.refreshSubConns(lb.resolvedBackendAddrs, true, lb.usePickFirst)
	}
	lb.mu.Unlock()
	return nil
}

