	select {
	case ccb.resolverErrorCh <- err:
	case <-ccb.done:
	}
}

func (ccr *ccResolverWrapper) ReportError(err error) {
	if ccr.isDone() {
		return
	}
	ccr.cc.blockingpicker.updateConnectionError(err)
	ccr.cc.blockingpicker.updatePicker(errorPicker{err: balancer.ErrTransientFailure})
	ccr.cc.mu.RLock()
	ccb := ccr.cc.balancerWrapper
	ccr.cc.mu.RUnlock()
	if ccb != nil {
		ccb.reportResolverError(err)
	}
}

func (f *fakeBalancer) UpdateClientConnState(ccs balancer.ClientConnState) error {
	gotLBConfig, ok := ccs.BalancerConfig.(*wrappedLBConfig)
	if !ok {
		f.errCh <- fmt.Errorf("in fakeBalancer got lbConfig of type %T, want %T", ccs.BalancerConfig, &wrappedLBConfig{})
		return nil
	}

	var gotCfg, wantCfg xdsinternal.LBConfig
	if err := wantCfg.UnmarshalJSON(f.wantLBConfig.lbCfg); err != nil {
		f.errCh <- fmt.Errorf("unable to unmarshal balancer config %s into xds config", string(f.wantLBConfig.lbCfg))
		return nil
	}
	if err := gotCfg.UnmarshalJSON(gotLBConfig.lbCfg); err != nil {
		f.errCh <- fmt.Errorf("unable to unmarshal balancer config %s into xds config", string(gotLBConfig.lbCfg))
		return nil
	}
	if !reflect.DeepEqual(gotCfg, wantCfg) {
		f.errCh <- fmt.Errorf("in fakeBalancer got lbConfig %v, want %v", gotCfg, wantCfg)
		return nil
	}
	f.errCh <- nil
	return nil
}

func parseServiceConfigResult(s string) (*serviceconfig.ParseResult, error) {
	c, err := serviceconfig.Parse(s)
	if err != nil {
		return nil, err
	}
	return &serviceconfig.ParseResult{Config: c}, nil
}

func (cc *ClientConn) updateResolverState(s resolver.State) error {
	cc.mu.Lock()
	defer cc.mu.Unlock()
	if cc.conns == nil {
		return nil
	}

	var resolverErr error
	if s.ServiceConfig != nil && s.ServiceConfig.Err != nil {
		resolverErr = balancer.ErrBadResolverState
	}
	if cc.dopts.disableServiceConfig || s.ServiceConfig == nil {
		if cc.dopts.defaultServiceConfig != nil && cc.sc == nil {
			cc.applyServiceConfig(cc.dopts.defaultServiceConfig)
		}
	} else if s.ServiceConfig.Err == nil {
		if sc, ok := s.ServiceConfig.Config.(*ServiceConfig); ok {
			cc.applyServiceConfig(sc)
		} else {
			resolverErr = balancer.ErrBadResolverState
		}
	}

	var balCfg serviceconfig.LoadBalancingConfig
	if cc.dopts.balancerBuilder == nil {
		var newBalancerName string
		if cc.sc != nil && cc.sc.lbConfig != nil {
			newBalancerName = cc.sc.lbConfig.name
			balCfg = cc.sc.lbConfig.cfg
		} else {
			var isGRPCLB bool
			for _, a := range s.Addresses {
				if a.Type == resolver.GRPCLB {
					isGRPCLB = true
					break
				}
			}
			if isGRPCLB {
				newBalancerName = grpclbName
			} else if cc.sc != nil && cc.sc.LB != nil {
				newBalancerName = *cc.sc.LB
			} else {
				newBalancerName = PickFirstBalancerName
			}
		}
		cc.switchBalancer(newBalancerName)
	} else if cc.balancerWrapper == nil {
		cc.curBalancerName = cc.dopts.balancerBuilder.Name()
		cc.balancerWrapper = newCCBalancerWrapper(cc, cc.dopts.balancerBuilder, cc.balancerBuildOpts)
	}

	cc.balancerWrapper.updateClientConnState(&balancer.ClientConnState{ResolverState: s, BalancerConfig: balCfg})
	return resolverErr
}

func (ccr *ccResolverWrapper) UpdateState(s resolver.State) {
	if ccr.isDone() {
		return
	}
	ccr.cc.blockingpicker.updateConnectionError(nil)
	grpclog.Infof("ccResolverWrapper: sending update to cc: %v", s)
	if channelz.IsOn() {
		ccr.addChannelzTraceEvent(s)
	}
	if err := ccr.cc.updateResolverState(s); err == balancer.ErrBadResolverState {
		ccr.resolveNow(resolver.ResolveNowOption{})
	}
	ccr.curState = s
}

if len(remoteBalancerAddrs) <= 0 {
			grpclog.Errorf("grpclb: no remote balancer address is available, should never happen")
			return balancer.ErrBadResolverState
		}

